    def runs(seq):
        out = []
        i = 0
        while i < len(seq):
            if seq[i] == bg:
                i += 1
                continue
            color = seq[i]
            j = i + 1
            while j < len(seq) and seq[j] == color:
                j += 1
            out.append((color, i, j))
            i = j
        return out

    candidates = []
    # Opposing horizontal edges
