            if a[0] == b[0] and a[2] - a[1] == b[2] - b[1]:
                candidates.append(("h", a, b))
    # Opposing vertical edges
    left = runs([grid[r][0] for r in range(h)])
    right = runs([grid[r][-1] for r in range(h)])
    for a in left:
        for b in right:
            if a[0] == b[0] and a[2] - a[1] == b[2] - b[1]:
                candidates.append(("v", a, b))

    if not candidates:
